window.MG_LAZY_DATA["data/lazy/resources/soft-v29-018-ee1d4b0c6506cf4d.json"]={sha256:"ee1d4b0c6506cf4d7a9f5dace143fdc3b19106c7a89662090417205dafb0628e",value:{"sources":[{"id":"v29-case-a01a53194c688ff9","url":"https://man7.org/linux/man-pages/man7/io_uring.7.html","title":"Linux io_uring: correlating submission and completion — primary reference","titleEn":"Linux io_uring: correlating submission and completion — primary reference","publisher":"Original project / standard / author","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"soft-v29-018","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"soft-v29-018","related":[{"id":"soft-v29-019","referenceUrls":["https://man7.org/linux/man-pages/man2/futex.2.html"],"title":"Linux futex：使用者快路徑與核心等待","titleEn":"Linux futex: user-space fast paths and kernel waiting","why":"用兩課的可觀察驗收條件比較模型邊界：研究5驗收：交付joined-io.csv、短讀續傳與ID反例；不宣稱測得實際io_uring吞吐。 請保留本研究的輸入、逐筆中間狀態與不符合條件時的處置。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 acceptance: Deliver joined-io.csv, a short-read continuation and ID counterexamples without claiming measured io_uring throughput. Retain inputs, intermediate state and the disposition when the criterion is not met.","difference":"畫lock word從0→1→0，列compare後與wait前的競爭；要求等待系統呼叫重新檢查預期值。","differenceEn":"Trace lock word0→1→0 and the race between comparison and wait, requiring the wait operation to recheck the expected value.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["非同步I/O需以user_data等識別碼關聯提交與完成；完成順序不保證等於提交順序。buffer生命週期須延續到完成。\n本課數值核對：3*4096 = 12288 B；另一項核對：4096+2048+4096 = 10240 B。兩項若屬不同量綱，不得直接相除或相減。","futex等待會比較記憶體值後決定是否睡眠；上層鎖協定仍須保證正確的原子操作與可見性。\n本課數值核對：(990*0.1+10*5)/1000 = 0.149 us；另一項核對：10/1000 = 0.01 slow_path_ratio。兩項若屬不同量綱，不得直接相除或相減。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Asynchronous I/O correlates submission and completion through identifiers such as user_data; completion order may differ from submission order. Buffers must live until completion.\nNumeric audit: 3*4096 = 12288 B; second audit: 4096+2048+4096 = 10240 B. Quantities with different dimensions must not be directly divided or subtracted.","A futex wait compares the memory value before sleeping; the higher-level lock protocol still needs correct atomics and memory visibility.\nNumeric audit: (990*0.1+10*5)/1000 = 0.149 us; second audit: 10/1000 = 0.01 slow_path_ratio. Quantities with different dimensions must not be directly divided or subtracted.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"soft-v29-028","referenceUrls":["https://git-scm.com/book/en/v2/Git-Internals-Git-Objects"],"title":"Git：內容定址物件與 Merkle 關係","titleEn":"Git: content-addressed objects and Merkle relationships","why":"用兩課的可觀察驗收條件比較模型邊界：研究5驗收：交付joined-io.csv、短讀續傳與ID反例；不宣稱測得實際io_uring吞吐。 請保留本研究的輸入、逐筆中間狀態與不符合條件時的處置。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 acceptance: Deliver joined-io.csv, a short-read continuation and ID counterexamples without claiming measured io_uring throughput. Retain inputs, intermediate state and the disposition when the criterion is not met.","difference":"建立blob header與內容bytes再hash；tree項保留全部十個檔名，不把去重誤作刪檔。","differenceEn":"Hash the blob header plus content bytes; keep all ten tree names instead of mistaking deduplication for file deletion.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["非同步I/O需以user_data等識別碼關聯提交與完成；完成順序不保證等於提交順序。buffer生命週期須延續到完成。\n本課數值核對：3*4096 = 12288 B；另一項核對：4096+2048+4096 = 10240 B。兩項若屬不同量綱，不得直接相除或相減。","Git物件身分由型別、長度與內容決定；tree保存名稱與物件參照。相同內容可共用blob，不代表不同路徑同一歷史。\n本課數值核對：1+2 = 3 blobs；另一項核對：10-3 = 7 blobs。兩項若屬不同量綱，不得直接相除或相減。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Asynchronous I/O correlates submission and completion through identifiers such as user_data; completion order may differ from submission order. Buffers must live until completion.\nNumeric audit: 3*4096 = 12288 B; second audit: 4096+2048+4096 = 10240 B. Quantities with different dimensions must not be directly divided or subtracted.","Git object identity includes type, length and content; trees store names and object references. Identical content can share a blob without sharing path history.\nNumeric audit: 1+2 = 3 blobs; second audit: 10-3 = 7 blobs. Quantities with different dimensions must not be directly divided or subtracted.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v29-case-8628e25393078597","url":"https://man7.org/linux/man-pages/man2/futex.2.html","title":"Linux futex: user-space fast paths and kernel waiting — primary reference","titleEn":"Linux futex: user-space fast paths and kernel waiting — primary reference","publisher":"Original project / standard / author","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v29-case-1bae43588fdbc11c","url":"https://git-scm.com/book/en/v2/Git-Internals-Git-Objects","title":"Git: content-addressed objects and Merkle relationships — primary reference","titleEn":"Git: content-addressed objects and Merkle relationships — primary reference","publisher":"Original project / standard / author","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
